    [1952] = { "Магический жезл", "Поговорите с Табетой по завершении ритуала." },
    [1953] = { "Возвращение на болота", "Поговорите с Табетой." },
    [1954] = { "Сфера подземного огня", "Принесите сферу Подземного огня Табете из Пылевых топей." },
    [1955] = { "Поединок с демоном", "Убейте демона сферы, а потом поговорите с Табетой." },
    [1956] = { "Сила Ульдамана", "Добудьте обсидиановый источник силы и принесите его Табете в Пылевые топи." },
    [1957] = { "Волнолов маны", "Убейте 12 волноловов маны за отведенное время." },
    [1958] = { "Небесная сила" },
    [2040] = { "Битва под землей", "Принесите Шони Молшунье в Штормград зубчатый спрек-механизм гномов из Мертвых копей." },
    [2198] = { "Рассыпавшееся ожерелье", "Найдите создателя ожерелья, чтобы узнать, чего оно стоит." },
    [2199] = { "Мудрость за деньги", "Принесите пять серебряных слитков Талвашу дель Кисселю в Стальгорн." },
    [2200] = { "Назад в Ульдаман", "Выясните, где именно в Ульдамане находится ожерелье Талваша. Убитый паладин, о котором он упоминал, был последним владельцем этого ожерелья." },
    [2201] = { "Время собирать камни", "Найдите рубин, сапфир, и топаз, которые спрятаны в разных местах Ульдамана. Когда найдете, свяжитесь с Талвашем дель Кисселем, используя фиал Видения, который он предоставил.\n\nИз дневника вы узнали следующее:\n*Рубин укрыт в забаррикадированном Тенегорне.\n*Топаз спрятан в урне в одной из областей, занятых троггами, недалеко от расположения дворфов Альянса.\n\n*Сапфир присвоил себе Гримлок, лидер троггов." },
    [2202] = { "В Ульдаман за реактивом", "Принести 12 грибов-малиновиков Джаркалу Замшелому Клыку в Каргат." },
    [2203] = { "Пробежка по Бесплодным землям-2", "Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Джаркалу Замшелому Клыку в Каргат." },
    [2204] = { "Восстановление ожерелья", "Добудьте источник энергии из самого мощного волшебного создания, которое найдете в Ульдамане и доставьте его Талвашу дель Кисселю в Стальгорн." },
    [2240] = { "Потайной чертог", "Прочитайте журнал Бейлога, исследуйте потайной чертог и потом доложите об увиденном геологу Грозовой Вершине." },
    [2258] = { "Пробежка по Бесплодным землям", "Принесите 5 вторых желудков канюка, 10 клыков скального койота и 5 осколков каменных элементалей Джаркалу Смешанному Лишайнику в Каргат." },
    [2278] = { "Платиновые диски", "Поговорите с каменным стражем и запомните все, что он расскажем вам. Когда он закончит свой пересказ событий древности, активируйте диски Норганнона." },
    [2279] = { "Платиновые диски", "Отнесите миниатюрную копию дисков Норганнона в Лигу исследователей в Стальгорне." },
    [2280] = { "Платиновые диски", "Отнесите миниатюрную копию дисков Норганнона тому, кому это будет весьма интересно." },
    [2283] = { "Пропавшее ожерелье", "Найдите на раскопках Ульдамана драгоценное ожерелье (возможно, поврежденное) и принесите его в Оргриммар Драну Дрофферсу." },
    [2284] = { "Пропавшее ожерелье, этап 2", "Разыщите ключ к местонахождению самоцветов в глубинах Ульдамана." },
    [2318] = { "Трудности перевода", "Найдите кого-нибудь, кто сможет перевести для вас дневник паладина. Ближайший к вам такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных землях." },
    [2338] = { "Трудности перевода", "Одолжите ожерелье Джаркалу. Взамен он переведет дневник." },
    [2339] = { "Найти самоцветы и источник энергии", "Добудьте все три самоцвета и источник энергии для ожерелья из Ульдамана и принесите их Джаркалу Замшелому Клыку в Каргат. Джаркал считает, что источник энергии можно найти у самой сильной твари в Ульдамане. \n\nИз дневника следует... \n* Рубин спрятан на огражденной завалами территории Тенегорна. \n*Топаз спрятан в урне на территорях троггов под боком у дворфов Альянса.\n*Сапфир забрал Гримлок, старейшина троггов." },
    [2340] = { "Принести самоцветы", "Доставьте ожерелье и драгоценности Драну Дрофферсу в Оргриммар." },
    [2341] = { "Пропавшее ожерелье, этап 3", "Навестите Джаркала Замшелого Клыка в Каргате." },
    [2342] = { "Возвращенные сокровища", "Принесите Патрику Гарретту в Подгород фамильное сокровище из сундука в Южном зале Ульдамана." },
    [2361] = { "Восстановление ожерелья" },
    [2398] = { "Потерянные дворфы", "Найдите Бейлога в Ульдамане." },
    [2418] = { "Силовые камни", "Принесите 8 дентриевых силовых камней и 8 энелиевых силовых камней Ригглфаззу в Бесплодные земли." },
    [2439] = { "Платиновые диски", "Отнесите наградной сертификат Дините Каменной Мантии в хранилище Стальгорна." },
    [2440] = { "Платиновые диски", "Отнесите наградной сертификат Бене Заиндевевшее Копыто в Громовой Утес." },
    [2500] = { "Пробежка по Бесплодным землям", "Добудьте в Бесплодных землях реагенты для Гхака Целителя и отнесите их ему в Телcамар." },
    [2501] = { "Пробежка по Бесплодным землям-2", "Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Гхаку Целителю в Телcамар." },
