    [2924] = { "Базовый элемент", "Принесите 12 базовых элементов Клацморту Гайкокруту в Стальгорн." },
    [2926] = { "Новая формула", "Соберите радиоактивный осадок, оставляемый облученными захватчиками и облученными погромщиками в пустую освинцованную склянку для проб. Принесите наполненную склянку Оззи Триггервольту в Каранос." },
