    [2937] = { "Призыв Шадры", "Убейте Шадру у алтаря Шадра'Алора и принесите ее яд аптекарю Лидону на Мельницу Таррен." },
    [2938] = { "Яд в Подгород", "Отнесите сверток опытному аптекарю Фаранеллу в Подгород." },
    [2945] = { "Покрытое грязью кольцо", "Придумайте, как отчистить кольцо, покрытое грязью." },
    [2946] = { "Посмотрим, что будет дальше", "Принесите миниатюрные платиновые диски к воротам Ульдума в Танарисе и проверьте, имеют ли диски отношение к воротам." },
    [2947] = { "Возвращение кольца", "Вы можете оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца." },
