    [2949] = { "Возвращение кольца", "Вы можете оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца." },
    [2950] = { "Переделка кольца", "Принесите сверкающее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Ноггу в Огргиммар." },
    [2951] = { "Чистер 5200!", "Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200." },
    [2952] = { "Чистер 5200!" },
    [2953] = { "Работа для Чистера" },
    [2954] = { "Каменный Страж", "Узнайте назначение Каменного Стража Норганнона, затем коснитесь пьедестала Ульдума в пустыне Танарис." },
    [2962] = { "Сильное зеленое свечение", "Отправляйтесь в Гномреган и принесите высокорадиоактивные образцы. Внимание: отходы нестабильны и довольно быстро разрушаются.\n\nВерните Оззи тяжелую освинцованную склянку для проб, когда задача будет выполнена." },
