    [2992] = { "Прорицание", "Дождитесь, пока Мрачная Тень не закончит ритуал прорицания." },
    [2993] = { "Назад во Внутренние земли", "Поговорите с укротителем грифонов Разящим Когтем." },
    [2994] = { "Спасение Остроклюва", "Пробейтесь в верхнюю часть Джинта'Алора, убейте коварную жрицу Ведьмису, возьмите у нее ключ от клетки и освободите Остроклюва." },
    [3042] = { "Троллье месиво", "Принесите 20 фиалов с Тролльим месивом." },
    [3341] = { "Да сгинет Хладовей", "Эндрю Браунелл поручил вам убить Амненнара Хладовея и принести его череп." },
    [3369] = { "Кошмары", "Принесите кошмарный осколок Хамуулу Руническому Тотему на Вершине Старейшин." },
    [3370] = { "Кошмары", "Принесите кошмарный осколок Матренгилу Медвежьей Лапе в Дарнас." },
    [3373] = { "Сущность Эраникуса", "Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме." },
    [3374] = { "Сущность Эраникуса", "Принесите камень Клятвы драконьего выводка Изеры и скованную сущность Эраникуса на Болото Печали. Там вам придется сделать выбор: помогать Драконам Изеры или нет." },
    [3375] = { "Запасной фиал", "Принесите зелье маны, уголь и сладкий нектар Талвашу дель Кисселю в Стальгорн, чтобы получить запасной фиал виденья Талваша." },
    [3380] = { "Затонувший храм", "Найдите Марвона Клепальщика в Танарисе." },
    [3441] = { "Божественное воздаяние", "Выслушайте Каларана Ветрореза." },
    [3442] = { "Неугасимое пламя", "Принести 4 сердца пламени и 4 меры масла големов Каларану Ветрорезу." },
    [3443] = { "Древко факела", "Принесите 8 окованных торием кинжалов Каларану Ветрорезу." },
