    [3447] = { "Тайна камня", "Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй." },
    [3452] = { "Защита пламени", "Найдите знак Рагнароса и принесите его Каларану Ветрорезу." },
    [3453] = { "Факел воздаяния", "Подождите, пока Каларан Ветрорез закончит факел Воздаяния." },
    [3454] = { "Факел воздаяния", "Возьмите факел воздаяния." },
    [3462] = { "Оруженосец Малтрейк", "Поговорите с оруженосцем Малтрейком." },
    [3463] = { "Задай им жару!", "Подожгите северную, южную, восточную и западную сторожевые башни с помощью факела воздаяния." },
    [3481] = { "Безделушки...", "Откройте сундук." },
