    [3520] = { "Духи крикунов", "Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе'кинье в Порт Хитрой Шестеренки." },
    [3523] = { "Плеть в холмах", "Если вы хотите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы, который он дал вам." },
    [3525] = { "Уничтожить идола", "Сопроводите Белнистраза к идолу свинобразов в Курганах Иглошкурых. \n\nЗащищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола." },
    [3527] = { "Пророчество Мошару", "Принесите первую и вторую таблички Мошару Йе'кинье в Танарис." },
