    [3636] = { "Нести свет", "Убейте Амненнара Хладовея в Курганах Иглошкурых." },
    [3701] = { "Дымящиеся руины Тауриссана", "Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессон." },
    [3702] = { "Дымящиеся руины Тауриссана", "Узнайте от королевского историка Аркессон историю Тауриссана." },
    [3765] = { "Проблема за морем", "Отправляйтесь в Аубердин к Гершалу Шепоту Ночи." },
    [3801] = { "Наследие Черного Железа", "Чтобы получить ключ от города, поговорите с Франклорном Искусником у гробницы Искусника на Черной горе." },
    [3802] = { "Наследие Черного Железа", "Убейте Финия Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника." },
    [3906] = { "Дисгармония пламени", "Отправьтесь в карьер у Черной горы и уничтожьте Подчинителя Пирона. По выполнению вернитесь к Громосерду." },
    [3907] = { "Дисгармония пламени", "Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию." },
    [3981] = { "Командир Гор'шак", "Найдите командира Гор'шака в Глубинах Черной горы. \n\nСудя по рисунку в записке, искать следует в темнице где-то вроде того." },
    [3982] = { "Что происходит?", "Защитите Гор'шака." },
    [4001] = { "Что происходит?", "Поговорите с дворфом по имени Каран Могучий Молот и соберите информацию о похищении принцессы Мойры Бронзобород. Передайте информацию Траллу в Оргриммар.\n\nВы вспоминаете слова Гор'шака о том, что Карана держат в темнице напротив." },
    [4002] = { "Восточные королевства", "Поговорите с Траллом." },
    [4003] = { "Спасение принцессы", "Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия." },
    [4004] = { "Спасенная принцесса", "Вернитесь к Траллу в крепость Громмаш, что в Оргриммаре." },
    [4022] = { "Вкус пламени", "Покажите Цирусу Раскаивателю сброшенную кожу черного дракона, полученную от Каларана Ветрореза." },
    [4023] = { "Вкус пламени", "Покажите Цирусу Раскаивателю доказательство своих деяний.\n\nВозникает чувство, что Цирус заранее сомневается в ваших качествах." },
    [4024] = { "Вкус пламени", "Отправьтесь в глубины Черной горы и убейте Бейл'Гора.\n\nИзвестно лишь то, что великан живет в глубинах. Воспользуйтесь измененной сброшенной шкурой черного дракона и возьмите из останков Бейл'Гора сущность Огня.\n\nОтнесите пойманную сущность Огня Цирусу Раскаивателю." },
    [4061] = { "Восстание машин", "Отправляйтесь в Пылающие степи и соберите 10 осколков элементалей для верховной жрицы Теодоры Мальвадании. \n\nТеодора упоминала, что осколки можно найти у элементалей и големов." },
    [4062] = { "Восстание машин", "Отнесите образец осколка элементаля Лотвилю Вериатусу. \n\nТеодора упоминала, что его лагерь находится на востоке." },
    [4063] = { "Восстание машин", "Найдите и убейте повелителя големов Аргелмаха. Принесите его голову Лотвилу. Также соберите 10 невредимых ядер стихий с беспощадных големов и созданий-завоевателей, охраняющих Аргелмаха. Информация передана посредством телепатии." },
    [4081] = { "УНИЧТОЖИТЬ НА МЕСТЕ: Дворфы Черного Железа", "Отправляйтесь в глубины Черной горы и уничтожьте подлых агрессоров! \n\nПо приказу полководца Клинозуба уничтожьте 15 охранников, 10 надсмотрщиков и 5 пехотинцев из клана Ярости Горна. Вернитесь сразу по выполнении задания." },
    [4082] = { "УНИЧТОЖИТЬ НА МЕСТЕ: Высокопоставленные чины Черного Железа", "Отправляйтесь в глубины Черной горы и уничтожьте подлых агрессоров! \n\nПо приказу полководца Клинозуба уничтожьте 10 медиков, 10 солдат и 10 офицеров из клана Ярости Горна. Вернитесь сразу по выполнении задания." },
    [4121] = { "Опасное положение", "Отконвоируйте пленника, Грарка Лорктуба, через Пылающие степи и Черную гору к Тлеющему ущелью.\n\nЛекслорт что-то говорил насчет того, что по другую сторону будут ждать его ребята, которые уведут Грарка в тюрьму.\n\nТакже отдайте Лекслорту ториевые оковы." },
    [4122] = { "Грарк Лоркруб", "Отправьтесь в Пылающие степи и найдите Грарка Лоркруба. Лекслорт упоминал, что в последний раз предателя видели в крепости Черной горы. \n\nПо обнаружении Грарка Лоркруба закуйте его в ториевые оковы и затем доставьте его от Черной горы к Тлеющему ущелью, Лекслорт и его подчиненные займутся допросом преступника." },
    [4123] = { "Сердце горы", "Принесите сердце горы Максворту Суперблеску в Пылающие степи." },
    [4126] = { "Харли Чернопых", "Найдите украденный рецепт Громоваров и верните его Рагнару Громовару в Каранос." },
    [4132] = { "Операция:смерть Кузне Гнева", "Отправляйтесь в Глубины Черной горы и убейте генерала Кузню Гнева. Вернитесь к полководцу Клинозубу по выполнении задания." },
    [4134] = { "Украденный рецепт громоварского", "Принесите рецепт светлого громоварского Вивиан Лягроб в Каргат." },
    [4136] = { "Риббли Крутипроб", "Принесите голову Риббли Юке Крутипроб в Пылающие степи." },
    [4141] = { "Муиджин и Ларион", "Соберите 15 кровоцветов и принесите их Муиджину." },
    [4142] = { "Визит к Грегану", "Отнесите кровоцвет Грегану Пивоплюю в Фералас." },
    [4143] = { "Туман зла", "Соберите 5 образцов тумана Аталаи и принесите их Муиджину в Кратер Ун'Горо." },
    [4144] = { "Ростки кровоцвета" },
    [4145] = { "Ларион и Муиджин", "Уничтожьте 5 кровоцветов-хлестунов, 5 кровоцветов-крепкозубов, 5 кровоцветов-живодеров и 5 кровоцветов-звероловов по просьбе Лариона из Укрытия Маршалла." },
    [4146] = { "Питание для шокера", "Доставьте незаряженный шокер и 5 образцов тумана Аталаи Лариону в Укрытие Маршалла." },
    [4147] = { "Мастерская Марвона", "Отправьтесь к Марвону Клепальщику в его мастерскую в Кабестане." },
    [4148] = { "Антикровоцветный шокер" },
    [4182] = { "Драконья угроза", "Убейте 15 детенышей черного дракона, 10 черных драконоидов, 4 черных драконид и 1 черного дракона." },
    [4183] = { "Подлинные хозяева", "Отправьтесь в Приозерье, что в Красногорье, и доставьте письмо Хелендиса Речного Мыса мировому судье Соломону." },
    [4184] = { "Подлинные хозяева", "Передайте обращение Соломона королю Вариану Ринну.\n\nКороль Ринн пребывает в крепости Штормграда." },
    [4185] = { "Подлинные хозяева", "Поговорите с Верховным лордом Болваром Фордрагоном после беседы с леди Катраной Престор." },
    [4186] = { "Подлинные хозяева", "Отнесите указ Ринна мировому судье Соломону в Приозерье." },
    [4201] = { "Приворотное зелье", "Принесите 4 листа крови Грома, 10 огромных серебряных слитков и наполненный сосуд Нагмары госпоже Нагмаре в Глубины Черной горы." },
    [4223] = { "Подлинные хозяева", "Поговорите с маршалом Максвеллом в Пылающих степях." },
    [4224] = { "Подлинные хозяева", "Поговорите с Джоном-Оборванцем." },
    [4241] = { "Маршал Винздор", "Отправляйтесь на Черную гору на северо-западе и войдите в Глубины Черной горы. Узнайте, что сталось с маршалом Виндзором.\n\nКажется, Джон-Оборванец говорил о том, что Виндзора утащили в темницу." },
    [4242] = { "Утраченная надежда", "Сообщите маршалу Максвеллу плохие новости. Его можно найти в Дозоре Морганы, что в Пылающих степях." },
    [4262] = { "Подчинитель Пирон", "Убейте подчинителя Пирона.\n\nКажется, Джалинда говорила, что Пирон охраняет каменоломню. Может, поискать его там?" },
    [4263] = { "Опалитель!", "Отыщите и уничтожьте лорда Опалителя в глубинах Черной горы!" },
    [4264] = { "Измятая записка", "Не исключено, что ваша находка заинтересует маршала Виндзора. Может быть, все не так плохо, и надежда еще жива." },
    [4282] = { "Проблеск надежды", "Верните маршалу Виндзору утерянную информацию.\n\nМаршал уверен, что информацией завладели повелитель големов Аргелмах и генерал Кузня Гнева." },
    [4286] = { "За сокровищем – с кулаками", "Добудьте 20 поясных сумок дворфов Черного Железа." },
    [4322] = { "Побег!", "Помогите маршалу Виндзору забрать вещи и освободить его друзей, после чего вернитесь к маршалу Максвеллу и получите дальнейшие инструкции." },
    [4341] = { "Каран Могучий Молот", "Пойдите в Глубины Черной горы и найдите Карана Могучего Молота.\n\nКороль упомянул, что Каран сидит там в плену – может, стоит поискать темницу." },
    [4342] = { "Рассказ Карана", "Выслушайте рассказ Карана Могучего Молота." },
    [4361] = { "Недобрые вести", "Вернитесь в Стальгорн и сообщите нехорошие новости королю Магни Бронзобороду." },
    [4362] = { "Судьба королевства", "Вернитесь в Глубины Черной горы и освободите принцессу Мойру Бронзобород от злобного императора Даграна Тауриссана." },
    [4363] = { "Королевский сюрприз", "Вернитесь в Стальгорн и переговорите с королем Магни Бронзобородом." },
    [4601] = { "Чистер 5200!", "Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200." },
    [4602] = { "Чистер 5200!", "Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200." },
    [4603] = { "Работа для Чистера" },
    [4604] = { "Работа для Чистера" },
    [4605] = { "Чистер 5200!" },
    [4606] = { "Чистер 5200!" },
    [4701] = { "Устранение опасности", "Отправьтесь на Пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами." },
    [4724] = { "Праматерь стаи", "Убейте Халикон, праматерь стаи воргов Кровавого Топора." },
    [4726] = { "Сущность детеныша дракона", "Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях." },
    [4729] = { "Редкие звери Киблера", "Отправьтесь на Пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру." },
    [4734] = { "Заморозка яйца", "Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье на Пике Черной горы." },
    [4735] = { "Сбор яиц", "Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях." },
    [4742] = { "Печать вознесения", "Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения.\n\nКамни могут быть у трех генералов: у воеводы Вуна из племени Тлеющего Терновника, у вождя Омокка из клана Черной Вершины и у повелителя Змейталака из клана Кровавого Топора." },
    [4743] = { "Печать вознесения", "Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю.\n\nКак только воля великого зверя ослабнет, надо немедленно положить перед ним заготовку печати вознесения и воспользоваться сферой Энергии дракона, чтобы подчинить себе его разум и направить его пламя на заготовку." },
    [4764] = { "Пряжка Роковой оснастки", "Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи." },
    [4765] = { "Доставить Риджвеллу", "Отнесите ящик Риджвелла Ремингтону Риджвеллу в крепость Штормграда." },
    [4768] = { "Табличка Темнокамня", "Принесите табличку Темного Камня тенемагу Вивиан Лягроб в Каргат." },
    [4771] = { "Рассветный гамбит", "Отнесите рассветный гамбит в демонстрационную комнату в Некроситете. Уничтожьте Вектуса и возвращайтесь к Бетине Биггльцинк." },
    [4787] = { "Древнее яйцо", "Принесите древнее яйцо Йе'кинье в Танарис." },
    [4788] = { "Последние таблички", "Принесите пятую и шестую таблички Мошару геологу Железному Башмаку в Танарисе." },
    [4808] = { "Фелнок Сталлист", "Отнесите письмо Тинки Фелноку Сталлисту в Круговзор, что в Зимних Ключах." },
    [4809] = { "Рога хладнокрылов", "Добудьте 8 безупречных рогов хладнокрыла." },
    [4810] = { "Возвращение к Тинки", "Отнесите ящик Фелнока Тинки Кипеллер в Пылающие степи. Ее можно найти возле Пламенеющего Стяга." },
    [4862] = { "Товар на любителя", "Отправьтесь на Пик Черной горы и принесите Киблеру 15 яиц скального паука.\n\nСудя по всему, яйца надо искать недалеко от пауков." },
    [4866] = { "Материнское молоко", "Найдите в самом сердце Пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд." },
    [4867] = { "Аррок Смертный Вопль", "Прочитайте записку Вароша. Принесите Варошу его амулет." },
    [4903] = { "Приказ полководца", "Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них важные бумаги Черной горы доставьте полководцу Клинозубу в Каргат." },
    [4941] = { "Мудрость Эйтригга", "Поговорите с Эйтриггом в Оргриммаре. После этого обратитесь к вождю Траллу. \n\nВ последний раз Эйтригг был в зале приемов Тралла." },
    [4974] = { "За Орду!", "Отправляйтесь на Пик Черной горы и убейте вождя Ренда Чернорука. Принесите его голову в Оргриммар." },
    [4981] = { "Агент Блестяшка", "Отправьтесь к Пику Черной горы и выясните, что сталось с Блестяшкой." },
    [4982] = { "Вещи Блестяшки", "Найдите вещи Блестяшки и верните их владелице. Блестяшка сказала, что она спрятала свое оборудование где-то на нижнем ярусе подземелья." },
    [4983] = { "Донесение Блестяшки", "Передайте донесение Блестяшки гроссмейстеру Лекслорту в Каргат." },
    [5001] = { "Вещи Блестяшки", "Найдите вещи Блестяшки и верните их владелице. Удачи!" },
    [5002] = { "Донесение Максвелла", "Передайте маршалу Максвеллу информацию Блестяшки." },
    [5047] = { "Айс Вентурон, к вашим услугам!", "Переговорите с Малифоем Черномолотом в Круговзоре." },
    [5063] = { "Шапка Алого Ученого", "Для изготовления шапки Алого Ученого вам нужно принести Малифою Черномолоту 1 Безупречную звериную шкуру; 5 истлевших шовных нитей поганища; 8 чародейских кристаллов; 5 зачарованных алых нитей. \n\nВы также должны будете уплатить 50 золотых монет за изготовление головного убора." },
    [5065] = { "Утраченные таблички Мошару", "Принесите третью и четвертую таблички Мошару геологу Железному Башмаку в Танарис." },
    [5067] = { "Поножи Тайны", "Для изготовления поножей Тайны вам нужно принести Малифою Черномолоту следующее: 1 безупречную звериную шкуру; 5 истлевших шовных нитей поганища, 5 арканитовых слитков, 5 порций бальзамировочного состава Ледяного Шепота; \n\nВам придется также заплатить 50 золотых монет за изготовление этого предмета." },
    [5068] = { "Кираса кровавой жажды", "Для изготовления кирасы кровавой жажды вам нужно будет принести Малифою Чернобойцу следующее: 1 безупречную звериную шкуру; 10 истлевших шовных нитей поганища; 5 арканитовых слитков; 5 шкур тени.\n\nВы также должны будете уплатить 50 золотых монет за изготовление доспеха." },
    [5081] = { "Миссия Максвелла", "Отправляйтесь на Пик Черной горы и устраните воеводу Вуна, вождя Омокка и повелителя Змейталака." },
    [5089] = { "Приказ генерала Драккисата", "Отнесите приказ генерала Драккисата маршалу Максвеллу в Пылающие степи." },
    [5102] = { "Кончина генерала Драккисата", "Отправьтесь на Пик Черной горы и устраните генерала Драккисата." },
    [5122] = { "Медальон веры" },
    [5125] = { "Слова Аурия" },
    [5126] = { "История Лоракса", "Поговорите с Лораксом. Выслушайте то, что он вам расскажет." },
    [5127] = { "Демонова кузня", "Отправляйтесь на Пик Черной горы и найдите Горалука Треснувшую Наковальню. Убейте его, а потом воткните в труп окровавленную пику. Таким образом пика вытянет его душу и окрасится ей.\n\nКроме того, вам нужно найти заготовку рунической кирасы.\n\nОтнесите пику и кирасу Лораксу в Зимних Ключах." },
    [5160] = { "Матрона-защитница", "Дойдите до Зимних Ключей и найдите Хале. Отдайте ей пластину чешуи Ауби." },
    [5161] = { "Гнев синих драконов", "Если у вас есть желание продолжить, поговорите снова с Хале." },
    [5162] = { "Гнев синих драконов", "Поговорите с Джезибой в Чумных землях. Он обитает в Андорале." },
    [5164] = { "Перечень Заблудших", "Прочитайте перечень Заблудших." },
    [5166] = { "Кираса хроматических полетов", "Джезиба \"Скульптор\" может сковать кирасу Всецветных драконов, если вы принесете ему следующее:\n\n1 всецветный панцирь.\n\n10 сверкающих всецветных чешуек.\n\n10 порций крови героев.\n\n10 истлевших шовных нитей поганища." },
    [5167] = { "Ножные латы всецветного воина", "Джезиба 'Скульптор' может сковать ножные латы Всецветного воина, если вы принесете ему следующее:\n\n1 всецветный панцирь.\n\n10 сверкающих всецветных чешуек.\n\n10 порций крови героев.\n\n5 шкур тени." },
    [5212] = { "Плоть не лжет", "Принесите 10 образцов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, сойдут ткани любой твари из Стратхольма." },
    [5213] = { "Вирус чумы", "Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк." },
    [5214] = { "Великий Фрас Сиаби", "Найдите табачную лавку Фраса Сиаби в Стратхольме, отыщите в ней пачку лучшего табака Сиаби и принесите ее Дымку ЛаРу." },
    [5243] = { "Святая вода", "Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Барталомею Чтимому, как только воды будет достаточно." },
    [5251] = { "Архивариус", "Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив." },
    [5262] = { "Ошеломляющая истина", "Отнесите голову Бальназара герцогу Николасу Зверенхоффу в Восточные Чумные земли." },
    [5263] = { "Быстрее, выше, сильнее", "Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу." },
    [5264] = { "Лорд Максвелл Тиросс", "Поговорите с лордом Максвеллом Тироссом. Вы найдете его внутри храма." },
    [5265] = { "Серебряный Оплот", "Откройте Серебряный Оплот и получите награду." },
    [5281] = { "Мятущиеся души", "Найдите Эгана. В последний раз его видели недалеко от Стратхольма." },
    [5282] = { "Мятущиеся души", "Стреляйте в призрачных и неупокоенных горожан на улицах Стратхольма из бластера Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу.\n\nОсвободите 15 неупокоенных душ и возвращайтесь к Эгану." },
    [5341] = { "Сокровище Баровых", "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову." },
    [5342] = { "Последний из Баровых", "Отправляйтесь в лагерь Промозглого Ветра, на земли Альянса, и убейте Вэлдона Барова. Отнесите его голову Алексию Барову.\n\nСоблюдайте осторожность – скорее всего, Вэлдона охраняют подхалимы из Альянса." },
    [5343] = { "Сокровище Баровых", "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Вэлдону Барову." },
    [5344] = { "Последний из Баровых", "Отправляйтесь в Бастион – на земли Орды – и убейте Алексия Барова. Отнесите его голову Вэлдону Барову.\n\nСоблюдайте осторожность – скорее всего, Алексия охраняет ордынская мразь." },
    [5382] = { "Доктор Теолен Крастинов по прозвищу Мясник", "Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркоффов. Выполнив задание, возвращайтесь к Еве Саркофф." },
    [5384] = { "Киртонос Глашатай", "Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос.\n\nСражайтесь как герой, не сдавайтесь! Уничтожьте Киртоноса и возвращайтесь к Еве Саркофф." },
    [5461] = { "Рас Ледяной Шепот – человек", "Отправляйтесь в высокогорья Арати, в руины Стромгарда. Поищите в Стромгарде книгу воспоминаний. Если удастся ее отыскать, отнесите ее мировому судье Мардуку." },
    [5462] = { "Рас Ледяной Шепот – гибель", "Отправляйтесь в часовню Последней Надежды в Восточных Чумных землях и найдите Леонида Барталомея Чтимого. Покажите ему книгу воспоминаний и расскажите обо всем, о чем удалось узнать." },
    [5463] = { "Дар Менетила", "Отправляйтесь в Стратхольм и отыщите Дар Менетила. Положите книгу воспоминаний на оскверненную землю." },
    [5464] = { "Дар Менетила", "Отнесите Книгу Души Леониду Барталомею в Восточные Чумные земли." },
    [5465] = { "Книга души", "Возвращайтесь к мировому судье Мардуку в Каэр Дарроу. Покажите ему Книгу Души." },
    [5466] = { "Рас Ледяной Шепот – лич", "Отыщите в Некроситете Раса Ледяного Шепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Ледяного Шепота. Отнесите голову мировому судье Мардуку." },
    [5515] = { "Мешок ужасов Крастинова", "Найдите в Некроситете Джандис Барову и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф." },
    [5518] = { "Броня огров Гордока", "Принесите 4 рулона рунической ткани, 8 кусков грубой кожи, 2 мотка рунной нити и огрскую дубильную кислоту Уззлу Наперстяку. Он прикован в секторе Гордока в Забытом Городе." },
    [5519] = { "Броня огров Гордока" },
    [5522] = { "Леонид Барталомей", "Принесите охлажденные яйца Леониду Барталомею в Восточные Чумные земли." },
    [5525] = { "Освободите Нотта!" },
    [5526] = { "Осколки сквернита", "Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Перевертня. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне." },
    [5527] = { "Реликварий Чистоты", "Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне." },
    [5528] = { "Лучшее пойло Гордока" },
    [5529] = { "Зачумленные детеныши дракона", "Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды." },
    [5531] = { "Бетина Биггльцинк", "Принесите охлажденные яйца Бетине Биггльцинк." },
    [5542] = { "Псы-демоны", "Убейте 20 карликовых чумных псов, 5 чумных псов и 5 бесноватых чумных псов. По выполнении задания вернитесь к Тириону Фордрингу." },
    [5543] = { "Окровавленные небеса", "Убейте 30 чумных нетопырей и вернитесь к Тириону Фордрингу." },
    [5544] = { "Мясо личинок-трупоедов", "Найдите личинок-падальщиков и падальщиков-пожирателей. Убейте побольше и наберите их мяса. Возвращайтесь к Тириону Фордрингу, когда насобираете 15 кусков мяса червей-трупоедов." },
    [5582] = { "Здоровая чешуя дракона", "Отнесите здоровую чешую дракона Бетине Биггльцинк в Часовню Последней Надежды в Восточные Чумные земли." },
    [5722] = { "В поисках потерянного ранца", "Обыщите Огненную Пропасть в поисках тела Маура Зловещего Тотема и найдите все необычные предметы." },
    [5723] = { "Испытание силы врага", "Найдите в Оргриммаре Огненную Пропасть, убейте 8 троггов и 8 шаманов Огненной Пропасти и возвращайтесь к Рахауро в Громовой Утес." },
    [5724] = { "Возвращение потерянной сумки", "Отнесите сумку Маура Зловещего Тотема Рахауро в Громовой Утес." },
    [5725] = { "Силы разрушения...", "Принесите книги \"Заклинания Тьмы\" и \"Заклятия Пустоты\" Вариматасу в Подгород." },
    [5726] = { "Тайные враги", "Принесите лейтенантский знак отличия Траллу в Оргриммар." },
    [5727] = { "Тайные враги", "Отнесите лейтенантский знак отличия Ниру Огненному Клинку. Убедите его в своей преданности Пылающему Клинку. Вернитесь к Траллу в Оргриммар." },
    [5728] = { "Тайные враги", "Убейте Баззалана и Жергоша Призывателя Духов и вернитесь в Оргриммар к Траллу." },
    [5729] = { "Тайные враги", "Поговорите с Ниру Огненным Клинком в Оргриммаре." },
    [5730] = { "Тайные враги", "Поговорите с Траллом в Оргриммаре." },
    [5742] = { "Искупление", "Выслушайте Тириона Фордринга." },
    [5761] = { "Убить тварь", "Спуститесь в Огненную Пропасть, убейте Тарагамана Ненасытного и принесите его сердце Ниру Огненному Клинку в Оргриммаре." },
    [5781] = { "Символ ушедших дней", "Отправляйтесь в Крипту – в самую южную часть Восточных Чумных земель – и добудьте молот Телана. Отнесите его Тириону Фордрингу." },
    [5845] = { "Символ утраченной чести", "Отправляйтесь в Северный Дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу." },
    [5846] = { "Символ семейной любви", "Отправляйтесь на остров Каэр Дарроу в центральной части Чумных земель и поищите там картину." },
    [5848] = { "Символ семейной любви", "Отправляйтесь в Стратхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину \"Символ семейной любви\", спрятанную за другой, изображающей две луны нашего мира.\n\nОтнесите картину Тириону Фордрингу." },
    [5861] = { "Найти Миранду", "Отправляйтесь к гробнице Утера, которая находится в южных Чумных землях. Покажите Миранде Колдунье подарок Тириона." },
    [5862] = { "Уловка против Алого Ордена", "Поговорите с Мирандой, пусть она наложит на вас Алую иллюзию. Отправляйтесь в Дольный Очаг, покуда она действует, и отнесите подарок Тириона верховному лорду Телану Фордрингу.\n\nДольный Очаг на севере, а Таэлан должен быть внутри Крепости Марденхольд." },
    [5944] = { "Во сне", "Выведите Телана Фордринга из Дольного Очага." },
    [6022] = { "Убийство во благо", "Отправляйтесь на восток в Перекресток Корина и убейте несколько населяющих его созданий Плети. Соберите 7 кусков живой гнили менее чем за 10 минут. С помощью ступки и пестика превратите живую гниль в сгущенную гниль." },
    [6042] = { "Мелочи нежизни", "Истребите 20 пагубных нетопырей и 10 чудовищных чумных нетопырей. После возвращайтесь к Натаносу Гнилостню." },
    [6133] = { "Охота на cледопытов", "Отправляйтесь в северные пределы Восточных Чумных земель и заполучите реестр Кель'Таласа. Документ находится где-то в Сторожке Кель'Литиен.\n\nТакже убейте 8 следопытов, 8 разведчиц дорог и 8 лесников." },
    [6135] = { "Проклятый Тенекрыл", "Выследите Тенекрыла и убейте его. Принесите полоску меха Тенекрыла Натаносу Гнилостню.\n\nГоворят, Тенекрыл рыщет в землях к северу от имения Марриса." },
    [6136] = { "Огромный червь", "Найдите и уничтожьте Мерзкослиза в северных пустошах Восточных Чумных земель. Возвращайтесь к Натаносу Гнилостню по выполнению задания." },
    [6163] = { "Рамштайн", "Отправляйтесь в Стратхольм и убейте Рамштайна Ненасытного. Принесите его голову Натаносу в качестве сувенира." },
    [6402] = { "Встреча в Штормграде", "Отправьтесь в Штормград и подойдите к городским воротам. Поговорите с оруженосцем Роу, чтобы он сообщил маршалу Виндзору о вашем прибытии." },
    [6403] = { "Великий Маскарад", "Сопроводите Реджинальда Виндзора через весь Штормград. Защитите его!" },
    [6501] = { "Око дракона", "Найдите существ, способных вернуть силу фрагменту амулета \"Око дракона\". Все, что об этих существах известно – это то, что они есть." },
    [6502] = { "Амулет Пламени дракона", "Добудьте кровь могучего черного дракона генерала Драккисата, которого можно найти сидящим на троне в залах Вознесения в Пике Черной горы." },
    [6521] = { "Нечестивый союз", "Принесите голову посла Малкина Брагору Кровопалу в Подгород." },
    [6522] = { "Нечестивый союз", "Отнесите маленький свиток Брагору Кровопалу в Королевский квартал Подгорода." },
    [6561] = { "Злодейство в Непроглядной Пучине", "Принесите голову Повелителя сумрака Келриса Башане Рунический Тотем в Громовой Утес." },
    [6562] = { "Угроза из Глубин", "Поговорите с Дже'неу Санкри в Ясеневом лесу." },
    [6563] = { "Сущность Аку'май", "Принесите 20 сапфиров Аку'май Дже'неу Санкри в Ясеневый лес." },
    [6564] = { "Верность древним богам", "Принесите отсыревшую записку Дже'неу Санкри в Ясеневый лес." },
    [6565] = { "Верность древним богам", "Убейте Лоргуса Джетта." },
    [6566] = { "Что принес ветер", "Выслушайте Тралла." },
    [6567] = { "Защитник Орды", "Найдите Рокаро в Деревне Ночных Охотников в Пустошах." },
    [6568] = { "Мастерица обмана", "Доставьте письмо Рокаро Миранде Колдунье в Западные Чумные земли." },
    [6569] = { "Иллюзии ока", "Отправляйтесь на Пик Черной горы и добудьте 20 глаз черных драконоидов. По выполнении задания вернитесь к Миранде Колдунье." },
    [6570] = { "Огнебор", "Отправляйтесь в Драконьи топи в Пылевых топях и найдите Логово Огнебора. Оказавшись внутри, наденьте амулет Обмана драконов и поговорите с Огнебором." },
    [6582] = { "Черепа: Провидец", "Найдите в Зимних Ключах избранного бойца синих дракона по имени Провидец и убейте его. С его черепом вернитесь к Огнебору." },
    [6583] = { "Черепа: Сомнус", "Убейте избранного бойца зеленых драконов Сомнуса и вернитесь с его черепом к Огнебору." },
    [6584] = { "Черепа: Хроналис", "Убейте Хроналиса, охраняющего Пещеры Времени в Пустыне Танарис и вернитесь с его черепом к Огнебору." },
    [6585] = { "Черепа: Акстроз", "Отправьтесь в Грим Батол и убейте Акстроза, избранного бойца красных драконов. Принесите его череп Огнебору." },
    [6601] = { "Вознесение", "Казалось бы, загадка разгадана. Вы знаете, что амулет Обмана Драконов, который сделала для вас Миранда Колдунья, не будет работать на Пике Черной горы. Найдите Рокаро и расскажите о ваших затруднениях. Покажите ему амулет Угасающего Пламени Дракона. Будем надеяться, он знает что делать." },
    [6602] = { "Кровь могучего черного дракона", "Отправляйтесь к Пику Черной горы и убейте генерала Драккисата. Соберите его кровь и вернитесь к Рокаро." },
    [6626] = { "Воинство зла", "Убейте 8 боевых стражей и 8 терноплетов из племени Иглошкурых, а также 8 сектанток из племени Мертвой Головы и возвращайтесь к Мириам Лунной Певице в Курганы Иглошкурых." },
    [6627] = { "Испытание знаний", "Дайте верный ответ на вопрос Брауга Тусклого Духа и поговорите с ним еще раз. Брауга можно в любое время найти в Когтистых горах." },
    [6628] = { "Испытание знаний", "Дайте верный ответ на вопрос Парквела Финталласа и поговорите с ним еще раз. Парквелла можно в любое время найти в Подгороде." },
    [6804] = { "Отравленная вода", "Исцелите отравленных элементалей в Восточных Чумных землях с помощью аспекта Нептулона. Принесите 12 браслетов колыхающихся волноплесков и аспект Нептулона герцогу Гидраксису в Азшару." },
    [6805] = { "Буря в пустыне", "Убейте 15 вихрей пыли и 15 пустынных грохотунов и возвращайтесь к герцогу Гидраксису в Азшару." },
    [6821] = { "Око Углевзора", "Принесите око Углевзора герцогу Гидраксису в Азшару." },
    [6822] = { "Огненные Недра", "Убейте 1 Повелителя огня, 1 лавового великана, 1 древнюю гончую Недр и 1 лавового волноплеска и возвращайтесь к герцогу Гидраксису в Азшару." },
    [6823] = { "Агент Гидраксиса", "Добейтесь уважительного отношеия к себе со стороны Гидраксианских Повелителей Вод, затем отправляйтесь к герцогу Гидраксису в Азшару." },
    [6824] = { "Руки врага", "Принесите руки Люцифрона, Сульфурона, Гееннаса и Шаззраха герцогу Гидраксису в Азшару." },
    [6921] = { "Среди руин", "Принесите глубинный сердечник Дже'неу Санкри на заставу Зорам'гар в Ясеневый лес." },
    [6922] = { "Барон Акванис", "Принесите странную водяную сферу Дже'неу Санкри в Непроглядную Пучину." },
    [6981] = { "Светящийся осколок", "Отправляйтесь в Кабестан и найдите там кого-нибудь, кто сможет вам рассказать об этом светящемся осколке.\n\nЗатем отнесите осколок туда, куда вас направят." },
    [7028] = { "Хрустальные орнаменты", "Соберите 15 терадрических хрустальных орнаментов для Ивы из Пустошей." },
    [7029] = { "Скверна Злоязыкого", "Наполните лазурный фиал с внутренним покрытием в оранжевом пруду Мародона.\n\nПолейте гнусь-лозу из наполненного фиала, чтобы изгнать ядовитую лозу.\n\nИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в Деревню Ночных Охотников." },
    [7041] = { "Скверна Злоязыкого", "Наполните лазурный фиал с внутренним покрытием в оранжевом пруду Мародона.\n\nПолейте гнусь-лозу из наполненного фиала, чтобы изгнать ядовитую лозу.\n\nИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела." },
    [7044] = { "Легенды Мародона", "Добудьте две части скипетра Келебраса – жезл Келебраса и бриллиант Келебраса.\n\nНайдите способ поговорить с Келебрасом." },
    [7046] = { "Скипетр Келебраса", "Помогите Келебрасу Освобожденному воссоздать скипетр Келебраса.\n\nПо завершении ритуала снова обратитесь к нему." },
    [7064] = { "Яблочко от яблоньки...", "Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от Деревни Ночных Охотников в Пустошах." },
    [7065] = { "Яблочко от яблоньки...", "Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши." },
    [7066] = { "Семя Жизни", "Найдите в Лунной поляне Ремула и отдайте ему Семя Жизни." },
    [7067] = { "Инструкции кентавра-парии", "Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей." },
    [7068] = { "Фрагменты осколка сумрака", "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель'наю в Оргриммар." },
    [7070] = { "Фрагменты осколка сумрака", "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей." },
    [7201] = { "Последний элемент", "Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лягроб также бормотала что-то про элементалей." },
    [7429] = { "Освободите Нотта!" },
    [7441] = { "Пузиллин и старейшина Азж'Тордин", "Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина.\n\nЕсли добудете книгу, вернитесь к Азж'Тордину в павильон Лорисс в Фераласе." },
    [7461] = { "Древнее безумие", "Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется.\n\nВойдите в Тюрьму Бессмер'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне.\n\nЕсли задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен'дралар." },
    [7462] = { "Сокровище Шен'дралар", "Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!" },
    [7463] = { "Магический напиток", "Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари." },
    [7481] = { "Эльфийские легенды", "Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в Лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать." },
    [7482] = { "Эльфийские легенды", "Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в крепость Оперенной Луны к книжнице Рунический Шип и сообщите ей все, что вам удалось узнать." },
    [7483] = { "Манускрипт скорости", "Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Скорости\", 1 безупречный черный алмаз, 2 больших сверкающих осколка и 2 образца крови героев, чтобы получить магический знак стремительности." },
    [7484] = { "Манускрипт средоточия", "Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Средоточия\", 1 безупречный черный алмаз, 4 больших сверкающих осколка и 2 образца шкуры тени, чтобы получить магический знак сосредоточения." },
    [7485] = { "Манускрипт защиты", "Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Защиты\", 1 безупречный черный алмаз, 2 больших сверкающих осколка и 1 истлевшую шовную нить поганища, чтобы получить магический знак защиты." },
    [7486] = { "Награда для героя", "Заберите свою награду из сундука Гидраксиса." },
    [7488] = { "Сеть Лефтендрис", "Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе." },
    [7489] = { "Сеть Лефтендрис", "Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе." },
    [7490] = { "Победа Орды", "Отнесите голову Ониксии Гаррошу в Оргриммар." },
    [7491] = { "На виду у всех", "Найдите властителя Рунтака на Аллее Силы." },
    [7493] = { "Все еще только начинается!" },
    [7495] = { "Славная победа Альянса", "Отнесите голову Ониксии королю Вариану Ринну в Штормград." },
    [7496] = { "Праздник добрых времен", "Найдите майора Маттингли на Аллее Героев." },
    [7497] = { "Все еще только начинается!" },
    [7503] = { "Величайшая гонка охотников", "Верните книгу законным владельцам." },
    [7507] = { "Справочник Форора", "Верните \"Справочник Форора по убийству драконов\" в Читальню." },
    [7508] = { "Ковка Кель'Серрара", "Отдайте тусклый и плоский эльфийский клинок сказителю Лидросу." },
    [7509] = { "Ковка Кель'Серрара", "Заставьте Ониксию дохнуть своим огненным дыханием на потускневший древний клинок. После этого схватите раскаленный древний клинок. Имейте в виду, что раскаленным он останется ненадолго, так что медлить не следует!\n\nПоследнее, что нужно сделать – это убить дракона и вонзить раскаленный древний клинок в его труп.\n\nСделайте это – и Кель'Серрар навеки станет вашим!" },
    [7562] = { "Мор'зул Вестник Крови", "Поговорите с Мор'зулом Вестником Крови у Алтаря Бурь в Пылающих степях." },
    [7563] = { "Ярость крови", "Принесите 30 бутылок крови яростных зверей Мор'зулу Вестнику Крови в Пылающие степи." },
    [7564] = { "Дикоглаз", "Принесите ларец Крови Горзиеки Дикоглазу в Алтарь Бурь, что в Пылающих степях." },
    [7629] = { "Доставка беса", "Отнесите беса в бутылке в алхимическую лабораторию Некроситета. После создания пергамента верните бутылку Горзиеки Дикоглазу." },
    [7637] = { "Жертва необходима", "Доберитесь до Стальгорна и получите курильницу экзорцизма у Верховного жреца Рохана. За курильницу нужно будет внести плату в размере 150 золотых монет." },
    [7638] = { "Лорд Грейсон Тенелом", "Поговорите с лордом Грейсоном Тенеломом в Соборном квартале Штормграда." },
    [7639] = { "Демонстрация истинного правосудия", "Принесите курильницу экзорцизма лорду Грейсону Тенелому в Соборный квартал Штормграда." },
    [7640] = { "Изгнание призраков из Долины Ужаса", "Используйте курильницу экзорцизма для вызова из-под земли призраков, мучающих Долину Ужаса. Когда убьете 25 духов долины Ужаса, вернитесь к лорду Грейсону Тенелому в Соборный квартал Штормграда." },
    [7641] = { "Работа Гриманда Элмора", "Поговорите с Гримандом Элмором в Квартале Дворфов Штормграда." },
    [7642] = { "Сбор необходимого", "Принесите Гриманду Элмору в Квартал Дворфов Штормграда 40 отрезов рунической ткани, 6 арканитовых слитков, 10 цветков слезы Артаса, 5 сосудов со святой водой Стратхольма и 150 золотых монет." },
    [7643] = { "Дух древнего коня", "Купите лошадиный корм для Духа древнего коня у Меридет Карлсон в Южнобережье.\n\nУбейте Тендриса Криводрева в башне Забытого Города в Фераласе и освободите духа. Накормите духа кормом и получите благословление для арканитового чепрака." },
    [7644] = { "Благословенный арканитовый чепрак", "Вернитесь вместе с благословенным арканитовым чепраком к лорду Грейсону Тенелому в Соборный квартал Штормграда." },
    [7646] = { "Магический кристалл", "Принесите азеротский алмаз и безупречный черный алмаз лорду Грейсону Тенелому в Соборный квартал Штормграда." },
    [7667] = { "Существенная помощь", "Принесите Сагорну Гребнестраннику на Аллею Мудрости в Оргриммаре азеротский алмаз и безупречный черный алмаз." },
    [7668] = { "Угроза Темного Губителя", "Используйте кристальный предсказатель в Главном склепе в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его.\n\nПринесите голову Темного Терзателя Сагорну Гривастому Страннику на Аллею Мудрости Оргриммара." },
    [7669] = { "Возвращение в Главный склеп" },
    [7761] = { "Распоряжения Ренда Чернорука", "Вот уж действительно идиот... Похоже, вам нужно найти это клеймо и выжечь на руке метку Драккисата, чтобы получить доступ к сфере Приказа.\n\nВ письме ясно сказано, что генерал Драккисат охраняет клеймо. Наверное, стоит проверить." },
    [7848] = { "Сродство с недрами", "Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте осколок из Огненных Недр. Принесите его Лотосу Хранителю Портала в Черной горе." },
    [7877] = { "Сокровище Шен'дралар", "Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!" },
    [8181] = { "Сопротивление Йекинье", "Поговорите с Йе'киньей." },
    [8182] = { "Длань Растахана", "Поговорите с Молтором из Тернистой долины." },
    [8905] = { "Серьезное предложение", "Добудьте 15 порций крови животных Зимних Ключей и 20 золотых монет и отдайте их вместе с наручами Буйного Сердца Делиане в Стальгорне." },
    [8906] = { "Серьезное предложение", "Добудьте 15 порций крови животных Зимних ключей и 20 золотых и отдайте их вместе с наручниками загонщика Делиане в Стальгорне." },
    [8907] = { "Серьезное предложение", "Добудьте 15 порций крови животных Зимних Ключей и 20 золотых монет и отдайте их вместе с наручниками Магистра Делиане в Стальгорне." },
    [8908] = { "Серьезное предложение", "Добудьте 15 порций крови животных Зимних ключей и 20 золотых и отдайте их вместе с наручами из светостали Делиане в Стальгорне." },
    [8909] = { "Серьезное предложение", "Добудьте 15 порций крови животных Зимних ключей и 20 золотых и отдайте их вместе с наручами Преданности Делиане в Стальгорне." },
    [8910] = { "Серьезное предложение", "Добудьте 15 порций крови животных Зимних Ключей и 20 золотых монет и отдайте их вместе с наручами Незаметности Делиане в Стальгорне." },
    [8911] = { "Серьезное предложение", "Добудьте 15 порций крови животных Зимних Ключей и 20 золотых монет и отдайте их вместе с наручами Багрового Тумана Делиане в Стальгорне." },
    [8912] = { "Серьезное предложение", "Добудьте 15 порций крови животных Зимних Ключей и 20 золотых монет и отдайте их вместе с наручами Доблести Делиане в Стальгорне." },
    [8913] = { "Серьезное предложение", "Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами дикого cердца Моквару в Оргриммар." },
    [8914] = { "Серьезное предложение", "Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручниками загонщика Моквару в Оргриммар." },
    [8915] = { "Серьезное предложение", "Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручниками Магистра Моквару в Оргриммар." },
    [8916] = { "Серьезное предложение", "Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами Преданности Моквару в Оргриммар." },
    [8917] = { "Серьезное предложение", "Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами Незаметности Моквару в Оргриммар." },
    [8918] = { "Серьезное предложение", "Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с поручьями Стихий Моквару в Оргриммар." },
    [8919] = { "Серьезное предложение", "Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами Багрового Тумана Моквару в Оргриммар." },
    [8920] = { "Серьезное предложение", "Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами Доблести Моквару в Оргриммар." },
    [8921] = { "Эктоплазматический дистиллятор", "Принести Муксу Маноскребу из Прибамбасска 1 сверхточный арканитовый преобразователь, 4 великих вечных субстанции, 10 порций масла каменного угря, 25 горстей вулканического пепла и 40 золотых." },
    [8922] = { "Сверхъестественное устройство", "Отнесите запечатанный контейнер с кровью Муксу Маноскребу в Прибамбасск в Танарисе." },
    [8923] = { "Сверхъестественное устройство", "Отнесите запечатанный ларчик с ядом Муксу Маноскребу в Прибамбасск." },
